package com.example.controllers;
import java.util.List; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import com.example.dtos.*; import com.example.services.UsuarioService;
@RestController @RequestMapping("/usuarios") public class UsuarioController {private final UsuarioService service;public UsuarioController(UsuarioService service){this.service=service;}@GetMapping public List<UsuarioResponseDTO> listar(){return service.listarTodos();}@GetMapping("/{id}") public ResponseEntity<UsuarioResponseDTO> buscar(@PathVariable Long id){return ResponseEntity.ok(service.buscar(id));}@PostMapping public ResponseEntity<UsuarioResponseDTO> criar(@RequestBody UsuarioRequestDTO d){return ResponseEntity.ok(service.salvar(d));}@PutMapping("/{id}") public ResponseEntity<UsuarioResponseDTO> atualizar(@PathVariable Long id,@RequestBody UsuarioRequestDTO d){return ResponseEntity.ok(service.atualizar(id,d));}@DeleteMapping("/{id}") public ResponseEntity<Void> deletar(@PathVariable Long id){service.deletar(id);return ResponseEntity.noContent().build();}}
